Plan: read the current lookup value from B6, find the matching row in column A, then collect row-1 headers whose values in that row are greater than 0. Write the first two collected headers into B9:B10 as plain values, leaving any unused answer cell empty.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

lookup = vws["B6"].value
if isinstance(lookup, str):
    lookup = lookup.strip()

def norm_key(v):
    if v is None:
        return None
    if isinstance(v, str):
        return v.strip()
    return v

target_row = None
for r in range(2, vws.max_row + 1):
    cell_val = vws.cell(row=r, column=1).value
    if norm_key(cell_val) == norm_key(lookup):
        target_row = r
        break

def is_positive(v):
    if isinstance(v, bool):
        return False
    if isinstance(v, (int, float)):
        return v > 0
    if isinstance(v, str):
        try:
            return float(v) > 0
        except ValueError:
            return False
    return False

found = []
if target_row is not None:
    for c in range(2, vws.max_column + 1):
        header = vws.cell(row=1, column=c).value
        value = vws.cell(row=target_row, column=c).value
        if header is None:
            continue
        if is_positive(value):
            if isinstance(header, str):
                header = header.strip()
            found.append(header)

for i in range(2):
    cell = ws.cell(row=9 + i, column=2)
    if i < len(found):
        cell.value = found[i]
    else:
        cell.value = None

wb.save(OUT)

print("lookup:", lookup)
print("target_row:", target_row)
print("found:", found[:2])
